mapper.select:
SELECT uph.id, uph.user_id, u.username, uph.change_ip, uph.created_at, uph.updated_at, uph.created_by, uph.updated_by FROM log_user_password_history uph LEFT JOIN sys_user u ON uph.user_id = u.id
AND uph.user_id = #{query.userId}
AND uph.created_at > = #{query.changeTimeStart}
AND uph.created_at < = #{query.changeTimeEnd}
AND uph.change_ip LIKE CONCAT( #{query.changeIp}, '%' )
ORDER BY uph.created_at DESC
